// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    EtherLotto c;
    function setUp() public { c = new EtherLotto(); }

    function testFuzz_property(uint256 ts, uint256 diff, address actor) public {
        vm.assume(actor != address(0) && actor.code.length == 0);
        // pin the chain values so the lottery is deterministic and observable
        vm.warp(ts);
        vm.roll(diff);
        // restrict to the LOSING outcome so the rule is unambiguous for every admissible input
        uint256 random = uint256(keccak256(abi.encodePacked(block.timestamp, block.difficulty))) % 2;
        vm.assume(random == 1);

        vm.deal(actor, 10);
        vm.prank(actor);
        c.play{value: 10}();

        // after a losing play the whole ticket amount remains in the pot
        assertTrue(c.pot() == 10, "pot must equal full ticket amount after losing play");
    }
}
